// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address owner = address(0xbeef);

    function setUp() public {
        vm.prank(owner);
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount <= 1e36);

        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(owner);
        c.withdrawAll();

        assertTrue(owner.balance == ownerBalanceBefore + contractBalanceBefore);
    }
}
